#include <config.h>
#include "../libelf/libelfP.h"  /* For NOTE_ALIGN4 and NOTE_ALIGN8.  */
#undef  _
#include "libdwflP.h"
#include "common.h"

#include <elf.h>
#include <gelf.h>
#include <inttypes.h>
#include <endian.h>
#include <unistd.h>
#include <fcntl.h>

#include <system.h>


/* A good size for the initial read from memory, if it's not too costly.
   This more than covers the phdrs and note segment in the average 64-bit
   binary.  */

#define INITIAL_READ    1024

#if __BYTE_ORDER == __LITTLE_ENDIAN
# define MY_ELFDATA     ELFDATA2LSB
#else
# define MY_ELFDATA     ELFDATA2MSB
#endif

struct elf_build_id
{
  void *memory;
  size_t len;
  GElf_Addr vaddr;
};

struct read_state
{
  Dwfl *dwfl;
  Dwfl_Memory_Callback *memory_callback;
  void *memory_callback_arg;
  void **buffer;
  size_t *buffer_available;
};

/* Return user segment index closest to ADDR but not above it.
   If NEXT, return the closest to ADDR but not below it.  */
static int
addr_segndx (Dwfl *dwfl, size_t segment, GElf_Addr addr, bool next)
{
  int ndx = -1;
  do
    {
      if (dwfl->lookup_segndx[segment] >= 0)
        ndx = dwfl->lookup_segndx[segment];
      if (++segment >= dwfl->lookup_elts - 1)
        return next ? ndx + 1 : ndx;
    }
  while (dwfl->lookup_addr[segment] < addr);

  if (next)
    {
      while (dwfl->lookup_segndx[segment] < 0)
        if (++segment >= dwfl->lookup_elts - 1)
          return ndx + 1;
      ndx = dwfl->lookup_segndx[segment];
    }

  return ndx;
}

/* Return whether there is SZ bytes available at PTR till END.  */

static bool
buf_has_data (const void *ptr, const void *end, size_t sz)
{
  return ptr < end && (size_t) (end - ptr) >= sz;
}

/* Read SZ bytes into *RETP from *PTRP (limited by END) in format EI_DATA.
   Function comes from src/readelf.c .  */

static bool
buf_read_ulong (unsigned char ei_data, size_t sz,
                const void **ptrp, const void *end, uint64_t *retp)
{
  if (! buf_has_data (*ptrp, end, sz))
    return false;

  union
  {
    uint64_t u64;
    uint32_t u32;
  } u;

  memcpy (&u, *ptrp, sz);
  (*ptrp) += sz;

  if (retp == NULL)
    return true;

  if (MY_ELFDATA != ei_data)
    {
      if (sz == 4)
        CONVERT (u.u32);
      else
        CONVERT (u.u64);
    }
  if (sz == 4)
    *retp = u.u32;
  else
    *retp = u.u64;
  return true;
}

/* Try to find matching entry for module from address MODULE_START to
   MODULE_END in NT_FILE note located at NOTE_FILE of NOTE_FILE_SIZE
   bytes in format EI_CLASS and EI_DATA.  */

static const char *
handle_file_note (GElf_Addr module_start, GElf_Addr module_end,
                  unsigned char ei_class, unsigned char ei_data,
                  const void *note_file, size_t note_file_size)
{
  if (note_file == NULL)
    return NULL;

  size_t sz;
  switch (ei_class)
    {
    case ELFCLASS32:
      sz = 4;
      break;
    case ELFCLASS64:
      sz = 8;
      break;
    default:
      return NULL;
    }

  const void *ptr = note_file;
  const void *end = note_file + note_file_size;
  uint64_t count;
  if (! buf_read_ulong (ei_data, sz, &ptr, end, &count))
    return NULL;
  if (! buf_read_ulong (ei_data, sz, &ptr, end, NULL)) // page_size
    return NULL;

  uint64_t maxcount = (size_t) (end - ptr) / (3 * sz);
  if (count > maxcount)
    return NULL;

  /* Where file names are stored.  */
  const char *fptr = ptr + 3 * count * sz;

  ssize_t firstix = -1;
  ssize_t lastix = -1;
  for (size_t mix = 0; mix < count; mix++)
    {
      uint64_t mstart, mend, moffset;
      if (! buf_read_ulong (ei_data, sz, &ptr, fptr, &mstart)
          || ! buf_read_ulong (ei_data, sz, &ptr, fptr, &mend)
          || ! buf_read_ulong (ei_data, sz, &ptr, fptr, &moffset))
        return NULL;
      if (mstart == module_start && moffset == 0)
        firstix = lastix = mix;
      if (firstix != -1 && mstart < module_end)
        lastix = mix;
      if (mend >= module_end)
        break;
    }
  if (firstix == -1)
    return NULL;

  const char *retval = NULL;
  for (ssize_t mix = 0; mix <= lastix; mix++)
    {
      const char *fnext = memchr (fptr, 0, (const char *) end - fptr);
      if (fnext == NULL)
        return NULL;
      if (mix == firstix)
        retval = fptr;
      if (firstix < mix && mix <= lastix && strcmp (fptr, retval) != 0)
        return NULL;
      fptr = fnext + 1;
    }
  return retval;
}

/* Return true iff we are certain ELF cannot match BUILD_ID of
   BUILD_ID_LEN bytes.  Pass DISK_FILE_HAS_BUILD_ID as false if it is
   certain ELF does not contain build-id (it is only a performance hit
   to pass it always as true).  */

static bool
invalid_elf (Elf *elf, bool disk_file_has_build_id,
             struct elf_build_id *build_id)
{
  if (! disk_file_has_build_id && build_id->len > 0)
    {
      /* Module found in segments with build-id is more reliable
         than a module found via DT_DEBUG on disk without any
         build-id.   */
      return true;
    }
  if (disk_file_has_build_id && build_id->len > 0)
    {
      const void *elf_build_id;
      ssize_t elf_build_id_len;

      /* If there is a build id in the elf file, check it.  */
      elf_build_id_len = INTUSE(dwelf_elf_gnu_build_id) (elf, &elf_build_id);
      if (elf_build_id_len > 0)
        {
          if (build_id->len != (size_t) elf_build_id_len
              || memcmp (build_id->memory, elf_build_id, build_id->len) != 0)
            return true;
        }
    }
  return false;
}

static void
finish_portion (struct read_state *read_state,
                void **data, size_t *data_size)
{
  if (*data_size != 0 && *data != NULL)
    (*read_state->memory_callback) (read_state->dwfl, -1, data, data_size,
                                    0, 0, read_state->memory_callback_arg);
}

static inline bool
read_portion (struct read_state *read_state,
              void **data, size_t *data_size,
              GElf_Addr start, size_t segment,
              GElf_Addr vaddr, size_t filesz)
{
  /* Check whether we will have to read the segment data, or if it
     can be returned from the existing buffer.  */
  if (filesz > *read_state->buffer_available
      || vaddr - start > *read_state->buffer_available - filesz
      /* If we're in string mode, then don't consider the buffer we have
         sufficient unless it contains the terminator of the string.  */
      || (filesz == 0 && memchr (vaddr - start + *read_state->buffer, '\0',
                                 (*read_state->buffer_available
                                  - (vaddr - start))) == NULL))
    {
      *data = NULL;
      *data_size = filesz;
      return !(*read_state->memory_callback) (read_state->dwfl,
                                              addr_segndx (read_state->dwfl,
                                                           segment, vaddr,
                                                           false),
                                              data, data_size, vaddr, filesz,
                                              read_state->memory_callback_arg);
    }

  /* We already have this whole note segment from our initial read.  */
  *data = vaddr - start + (*read_state->buffer);
  *data_size = 0;
  return false;
}

int
dwfl_segment_report_module (Dwfl *dwfl, int ndx, const char *name,
                            Dwfl_Memory_Callback *memory_callback,
                            void *memory_callback_arg,
                            Dwfl_Module_Callback *read_eagerly,
                            void *read_eagerly_arg,
                            const void *note_file, size_t note_file_size,
                            const struct r_debug_info *r_debug_info)
{
  size_t segment = ndx;
  struct read_state read_state;

  if (segment >= dwfl->lookup_elts)
    segment = dwfl->lookup_elts - 1;

  while (segment > 0
         && (dwfl->lookup_segndx[segment] > ndx
             || dwfl->lookup_segndx[segment] == -1))
    --segment;

  while (dwfl->lookup_segndx[segment] < ndx)
    if (++segment == dwfl->lookup_elts)
      return 0;

  GElf_Addr start = dwfl->lookup_addr[segment];

  /* First read in the file header and check its sanity.  */

  void *buffer = NULL;
  size_t buffer_available = INITIAL_READ;
  Elf *elf = NULL;
  int fd = -1;

  read_state.dwfl = dwfl;
  read_state.memory_callback = memory_callback;
  read_state.memory_callback_arg = memory_callback_arg;
  read_state.buffer = &buffer;
  read_state.buffer_available = &buffer_available;

  /* We might have to reserve some memory for the phdrs.  Set to NULL
     here so we can always safely free it.  */
  void *phdrsp = NULL;

  if (! (*memory_callback) (dwfl, ndx, &buffer, &buffer_available,
                            start, sizeof (Elf64_Ehdr), memory_callback_arg)
      || memcmp (buffer, ELFMAG, SELFMAG) != 0)
    goto out;

  /* Extract the information we need from the file header.  */
  const unsigned char *e_ident;
  unsigned char ei_class;
  unsigned char ei_data;
  uint16_t e_type;
  union
  {
    Elf32_Ehdr e32;
    Elf64_Ehdr e64;
  } ehdr;
  GElf_Off phoff;
  uint_fast16_t phnum;
  uint_fast16_t phentsize;
  GElf_Off shdrs_end;
  Elf_Data xlatefrom =
    {
      .d_type = ELF_T_EHDR,
      .d_buf = (void *) buffer,
      .d_version = EV_CURRENT,
    };
  Elf_Data xlateto =
    {
    {
      .d_type = ELF_T_EHDR,
      .d_buf = &ehdr,
      .d_size = sizeof ehdr,
      .d_version = EV_CURRENT,
    };
  e_ident = ((const unsigned char *) buffer);
  ei_class = e_ident[EI_CLASS];
  ei_data = e_ident[EI_DATA];
  switch (ei_class)
    {
    case ELFCLASS32:
      xlatefrom.d_size = sizeof (Elf32_Ehdr);
      if (elf32_xlatetom (&xlateto, &xlatefrom, ei_data) == NULL)
        goto out;
      e_type = ehdr.e32.e_type;
      phoff = ehdr.e32.e_phoff;
      phnum = ehdr.e32.e_phnum;
      phentsize = ehdr.e32.e_phentsize;
      if (phentsize != sizeof (Elf32_Phdr))
        goto out;
      /* NOTE if the number of sections is > 0xff00 then e_shnum
         is zero and the actual number would come from the section
         zero sh_size field. We ignore this here because getting shdrs
         is just a nice bonus (see below in the type == PT_LOAD case
         where we trim the last segment).  */
      shdrs_end = ehdr.e32.e_shoff + ehdr.e32.e_shnum * sizeof (Elf32_Shdr);
      break;

    case ELFCLASS64:
      xlatefrom.d_size = sizeof (Elf64_Ehdr);
      if (elf64_xlatetom (&xlateto, &xlatefrom, ei_data) == NULL)
        goto out;
      e_type = ehdr.e64.e_type;
      phoff = ehdr.e64.e_phoff;
      phnum = ehdr.e64.e_phnum;
      phentsize = ehdr.e64.e_phentsize;
      if (phentsize != sizeof (Elf64_Phdr))
        goto out;
      /* See the NOTE above for shdrs_end and ehdr.e32.e_shnum.  */
      shdrs_end = ehdr.e64.e_shoff + ehdr.e64.e_shnum * sizeof (Elf64_Shdr);
      break;

    default:
      goto out;
    }

  /* The file header tells where to find the program headers.
     These are what we need to find the boundaries of the module.
     Without them, we don't have a module to report.  */

  if (phnum == 0)
    goto out;

  xlatefrom.d_type = xlateto.d_type = ELF_T_PHDR;
  xlatefrom.d_size = phnum * phentsize;

  void *ph_buffer = NULL;
  size_t ph_buffer_size = 0;
  if (read_portion (&read_state, &ph_buffer, &ph_buffer_size,
                    start, segment,
                    start + phoff, xlatefrom.d_size))
    goto out;

  /* ph_buffer_size will be zero if we got everything from the initial
     buffer, otherwise it will be the size of the new buffer that
     could be read.  */
  if (ph_buffer_size != 0)
    xlatefrom.d_size = ph_buffer_size;

  xlatefrom.d_buf = ph_buffer;

  bool class32 = ei_class == ELFCLASS32;
  size_t phdr_size = class32 ? sizeof (Elf32_Phdr) : sizeof (Elf64_Phdr);
  if (unlikely (phnum > SIZE_MAX / phdr_size))
    goto out;
  const size_t phdrsp_bytes = phnum * phdr_size;
  phdrsp = malloc (phdrsp_bytes);
  if (unlikely (phdrsp == NULL))
    goto out;

  xlateto.d_buf = phdrsp;
  xlateto.d_size = phdrsp_bytes;

  /* Track the bounds of the file visible in memory.  */
  GElf_Off file_trimmed_end = 0; /* Proper p_vaddr + p_filesz end.  */
  GElf_Off file_end = 0;         /* Rounded up to effective page size.  */
  GElf_Off contiguous = 0;       /* Visible as contiguous file from START.  */
  GElf_Off total_filesz = 0;     /* Total size of data to read.  */

  /* Collect the bias between START and the containing PT_LOAD's p_vaddr.  */
  GElf_Addr bias = 0;
  bool found_bias = false;

  /* Collect the unbiased bounds of the module here.  */
  GElf_Addr module_start = -1l;
  GElf_Addr module_end = 0;
  GElf_Addr module_address_sync = 0;

  /* If we see PT_DYNAMIC, record it here.  */
  GElf_Addr dyn_vaddr = 0;
  GElf_Xword dyn_filesz = 0;

  /* Collect the build ID bits here.  */
  struct elf_build_id build_id;
  build_id.memory = NULL;
  build_id.len = 0;
  build_id.vaddr =0;

  Elf32_Phdr *p32 = phdrsp;
  Elf64_Phdr *p64 = phdrsp;
  if ((ei_class == ELFCLASS32
       && elf32_xlatetom (&xlateto, &xlatefrom, ei_data) == NULL)
      || (ei_class == ELFCLASS64
          && elf64_xlatetom (&xlateto, &xlatefrom, ei_data) == NULL))
    {
      found_bias = false; /* Trigger error check */
    }
  else
    {
      /* Consider each of the program headers we've read from the image.  */
      for (uint_fast16_t i = 0; i < phnum; ++i)
        {
          bool is32 = (ei_class == ELFCLASS32);
          GElf_Word type = is32 ? p32[i].p_type : p64[i].p_type;
          GElf_Addr vaddr = is32 ? p32[i].p_vaddr : p64[i].p_vaddr;
          GElf_Xword memsz = is32 ? p32[i].p_memsz : p64[i].p_memsz;
          GElf_Off offset = is32 ? p32[i].p_offset : p64[i].p_offset;
          GElf_Xword filesz = is32 ? p32[i].p_filesz : p64[i].p_filesz;
          GElf_Xword align = is32 ? p32[i].p_align : p64[i].p_align;

          if (type == PT_DYNAMIC)
            {
              dyn_vaddr = vaddr;
              dyn_filesz = filesz;
            }
          else if (type == PT_NOTE)
            {
              /* If we have already seen a build ID, we don't care any more.  */
              if (build_id.memory != NULL || filesz == 0)
                continue; /* Next header */

              /* We calculate from the p_offset of the note segment,
               because we don't yet know the bias for its p_vaddr.  */
              const GElf_Addr note_vaddr = start + offset;
              void *data;
              size_t data_size;
              if (read_portion (&read_state, &data, &data_size,
                                start, segment, note_vaddr, filesz))
                continue; /* Next header */

              /* data_size will be zero if we got everything from the initial
                 buffer, otherwise it will be the size of the new buffer that
                 could be read.  */
              if (data_size != 0)
                filesz = data_size;

              assert (sizeof (Elf32_Nhdr) == sizeof (Elf64_Nhdr));

              void *notes;
              if (ei_data == MY_ELFDATA)
                notes = data;
              else
                {
                  const unsigned int xencoding = ehdr.e32.e_ident[EI_DATA];

                  notes = malloc (filesz);
                  if (unlikely (notes == NULL))
                    continue; /* Next header */
                  xlatefrom.d_type = xlateto.d_type = (align == 8
                                                       ? ELF_T_NHDR8
                                                       : ELF_T_NHDR);
                  xlatefrom.d_buf = (void *) data;
                  xlatefrom.d_size = filesz;
                  xlateto.d_buf = notes;
                  xlateto.d_size = filesz;
                  if (elf32_xlatetom (&xlateto, &xlatefrom, xencoding) == NULL)
                    {
                      free (notes);
                      finish_portion (&read_state, &data, &data_size);
                      continue;
                    }
                }

              const GElf_Nhdr *nh = notes;
              size_t len = 0;
              while (filesz > len + sizeof (*nh))
                {
                  const void *note_name;
                  const void *note_desc;

                  len += sizeof (*nh);
                  note_name = notes + len;

                  len += nh->n_namesz;
                  len = align == 8 ? NOTE_ALIGN8 (len) : NOTE_ALIGN4 (len);
                  note_desc = notes + len;

                  if (unlikely (filesz < len + nh->n_descsz))
                    break;

                  if (nh->n_type == NT_GNU_BUILD_ID
                      && nh->n_descsz > 0
                      && nh->n_namesz == sizeof "GNU"
                      && !memcmp (note_name, "GNU", sizeof "GNU"))
                    {
                      build_id.vaddr = (note_desc
                                        - (const void *) notes
                                        + note_vaddr);
                      build_id.len = nh->n_descsz;
                      build_id.memory = malloc (build_id.len);
                      if (likely (build_id.memory != NULL))
                        memcpy (build_id.memory, note_desc, build_id.len);
                      break;
                    }

                  len += nh->n_descsz;
                  len = align == 8 ? NOTE_ALIGN8 (len) : NOTE_ALIGN4 (len);
                  nh = (void *) notes + len;
                }

              if (notes != data)
                free (notes);
              finish_portion (&read_state, &data, &data_size);
            }
          else if (type == PT_LOAD)
            {
              align = (dwfl->segment_align > 1
                       ? dwfl->segment_align : (align ?: 1));

              GElf_Addr vaddr_end = (vaddr + memsz + align - 1) & -align;
              GElf_Addr filesz_vaddr = (filesz < memsz
                                        ? vaddr + filesz : vaddr_end);
              GElf_Off filesz_offset = filesz_vaddr - vaddr + offset;

              if (file_trimmed_end < offset + filesz)
                {
                  file_trimmed_end = offset + filesz;

                  /* Trim the last segment so we don't bother with zeros
                     in the last page that are off the end of the file.
                     However, if the extra bit in that page includes the
                     section headers, keep them.  */
                  if (shdrs_end <= filesz_offset
                      && shdrs_end > file_trimmed_end)
                    {
                      filesz += shdrs_end - file_trimmed_end;
                      file_trimmed_end = shdrs_end;
                    }
                }

              total_filesz += filesz;

              if (file_end < filesz_offset)
                {
                  file_end = filesz_offset;
                  if (filesz_vaddr - start == filesz_offset)
                    contiguous = file_end;
                }

              if (!found_bias && (offset & -align) == 0
                  && likely (filesz_offset >= phoff + phnum * phentsize))
                {
                  bias = start - vaddr;
                  found_bias = true;
                }

              if ((vaddr & -align) < module_start)
                {
                  module_start = vaddr & -align;
                  module_address_sync = vaddr + memsz;
                }

              if (module_end < vaddr_end)
                module_end = vaddr_end;
            }
        }
    }

  finish_portion (&read_state, &ph_buffer, &ph_buffer_size);

  /* We must have seen the segment covering offset 0, or else the ELF
     header we read at START was not produced by these program headers.  */
  if (unlikely (!found_bias))
    {
      free (build_id.memory);
      goto out;
    }

  /* Now we know enough to report a module for sure: its bounds.  */
  module_start += bias;
  module_end += bias;

  dyn_vaddr += bias;

  /* NAME found from link map has precedence over DT_SONAME possibly read
     below.  */
  bool name_is_final = false;

  /* Try to match up DYN_VADDR against L_LD as found in link map.
     Segments sniffing may guess invalid address as the first read-only memory
     mapping may not be dumped to the core file (if ELF headers are not dumped)
     and the ELF header is dumped first with the read/write mapping of the same
     file at higher addresses.  */
  if (r_debug_info != NULL)
    for (const struct r_debug_info_module *module = r_debug_info->module;
         module != NULL; module = module->next)
      if (module_start <= module->l_ld && module->l_ld < module_end)
        {
          /* L_LD read from link map must be right while DYN_VADDR is unsafe.
             Therefore subtract DYN_VADDR and add L_LD to get a possibly
             corrective displacement for all addresses computed so far.  */
          GElf_Addr fixup = module->l_ld - dyn_vaddr;
          if ((fixup & (dwfl->segment_align - 1)) == 0
              && module_start + fixup <= module->l_ld
              && module->l_ld < module_end + fixup)
            {
              module_start += fixup;
              module_end += fixup;
              dyn_vaddr += fixup;
              bias += fixup;
              if (module->name[0] != '\0')
                {
                  name = basename (module->name);
                  name_is_final = true;
                }
              break;
            }
        }

  if (r_debug_info != NULL)
    {
      bool skip_this_module = false;
      for (struct r_debug_info_module *module = r_debug_info->module;
           module != NULL; module = module->next)
        if ((module_end > module->start && module_start < module->end)
            || dyn_vaddr == module->l_ld)
          {
            if (module->elf != NULL
                && invalid_elf (module->elf, module->disk_file_has_build_id,
                                &build_id))
              {
                elf_end (module->elf);
                close (module->fd);
                module->elf = NULL;
                module->fd = -1;
              }
            if (module->elf != NULL)
              {
                /* Ignore this found module if it would conflict in address
                   space with any already existing module of DWFL.  */
                skip_this_module = true;
              }
          }
      if (skip_this_module)
        {
          free (build_id.memory);
          goto out;
        }
    }

  const char *file_note_name = handle_file_note (module_start, module_end,
                                                 ei_class, ei_data,
                                                 note_file, note_file_size);
  if (file_note_name)
    {
      name = file_note_name;
      name_is_final = true;
      bool invalid = false;
      fd = open (name, O_RDONLY);
      if (fd >= 0)
        {
          Dwfl_Error error = __libdw_open_file (&fd, &elf, true, false);
          if (error == DWFL_E_NOERROR)
            invalid = invalid_elf (elf, true /* disk_file_has_build_id */,
                                   &build_id);
        }
      if (invalid)
        {
          /* The file was there, but the build_id didn't match.  We
             still want to report the module, but need to get the ELF
             some other way if possible.  */
          close (fd);
          fd = -1;
          elf_end (elf);
          elf = NULL;
        }
    }

  /* Our return value now says to skip the segments contained
     within the module.  */
  ndx = addr_segndx (dwfl, segment, module_end, true);

  /* Examine its .dynamic section to get more interesting details.
     If it has DT_SONAME, we'll use that as the module name.
     If it has a DT_DEBUG, then it's actually a PIE rather than a DSO.
     We need its DT_STRTAB and DT_STRSZ to decipher DT_SONAME,
     and they also tell us the essential portion of the file
     for fetching symbols.  */
  GElf_Addr soname_stroff = 0;
  GElf_Addr dynstr_vaddr = 0;

250  static void
   251  finish_portion (struct read_state *read_state,
   252                  void **data, size_t *data_size)
   253  {
   254    if (*data_size != 0 && *data != NULL)
   255      (*read_state->memory_callback) (read_state->dwfl, -1, data, data_size,
   256                                      0, 0, read_state->memory_callback_arg);
   257  }
   258
   259  static inline bool
   260  read_portion (struct read_state *read_state,
   261                void **data, size_t *data_size,
   262                GElf_Addr start, size_t segment,
   263                GElf_Addr vaddr, size_t filesz)
   264  {
   265    /* Check whether we will have to read the segment data, or if it
   266       can be returned from the existing buffer.  */
   267    if (filesz > *read_state->buffer_available
   268        || vaddr - start > *read_state->buffer_available - filesz
   269        /* If we're in string mode, then don't consider the buffer we have
   270           sufficient unless it contains the terminator of the string.  */
   271        || (filesz == 0 && memchr (vaddr - start + *read_state->buffer, '\0',
   272                                   (*read_state->buffer_available
   273                                    - (vaddr - start))) == NULL))
   274      {
   275        *data = NULL;
   276        *data_size = filesz;
   277        return !(*read_state->memory_callback) (read_state->dwfl,
   278                                                addr_segndx (read_state->dwfl,
   279                                                             segment, vaddr,
   280                                                             false),
   281                                                data, data_size, vaddr, filesz,
   282                                                read_state->memory_callback_arg);
   283      }
   284
   285    /* We already have this whole note segment from our initial read.  */
   286    *data = vaddr - start + (*read_state->buffer);
   287    *data_size = 0;
   288    return false;
   289  }
   290
   291  int
   292  dwfl_segment_report_module (Dwfl *dwfl, int ndx, const char *name,
   293                              Dwfl_Memory_Callback *memory_callback,
   294                              void *memory_callback_arg,
   295                              Dwfl_Module_Callback *read_eagerly,
   296                              void *read_eagerly_arg,
   297                              const void *note_file, size_t note_file_size,
   298                              const struct r_debug_info *r_debug_info)
   299  {
   300    size_t segment = ndx;
   301    struct read_state read_state;
   302
   303    if (segment >= dwfl->lookup_elts)
   304      segment = dwfl->lookup_elts - 1;
   305
   306    while (segment > 0
   307           && (dwfl->lookup_segndx[segment] > ndx
   308               || dwfl->lookup_segndx[segment] == -1))
   309      --segment;
   310
   311    while (dwfl->lookup_segndx[segment] < ndx)
   312      if (++segment == dwfl->lookup_elts)
   313        return 0;
   314
   315    GElf_Addr start = dwfl->lookup_addr[segment];
   316
   317    /* First read in the file header and check its sanity.  */
   318
   319    void *buffer = NULL;
   320    size_t buffer_available = INITIAL_READ;
   321    Elf *elf = NULL;
   322    int fd = -1;
   323
   324    read_state.dwfl = dwfl;
   325    read_state.memory_callback = memory_callback;
   326    read_state.memory_callback_arg = memory_callback_arg;
   327    read_state.buffer = &buffer;
   328    read_state.buffer_available = &buffer_available;
   329
   330    /* We might have to reserve some memory for the phdrs.  Set to NULL
   331       here so we can always safely free it.  */
   332    void *phdrsp = NULL;
   333
   334    if (! (*memory_callback) (dwfl, ndx, &buffer, &buffer_available,
   335                              start, sizeof (Elf64_Ehdr), memory_callback_arg)
   336        || memcmp (buffer, ELFMAG, SELFMAG) != 0)
   337      goto out;
   338
   339    /* Extract the information we need from the file header.  */
   340    const unsigned char *e_ident;
   341    unsigned char ei_class;
   342    unsigned char ei_data;
   343    uint16_t e_type;
   344    union
   345    {
   346      Elf32_Ehdr e32;
   347      Elf64_Ehdr e64;
   348    } ehdr;
   349    GElf_Off phoff;
   350    uint_fast16_t phnum;
   351    uint_fast16_t phentsize;
   352    GElf_Off shdrs_end;
   353    Elf_Data xlatefrom =
   354      {
   355        .d_type = ELF_T_EHDR,
   356        .d_buf = (void *) buffer,
   357        .d_version = EV_CURRENT,
   358      };
   359    Elf_Data xlateto =
   360      {
   361        .d_type = ELF_T_EHDR,
   362        .d_buf = &ehdr,
   363        .d_size = sizeof ehdr,
   364        .d_version = EV_CURRENT,
   365      };
   366    e_ident = ((const unsigned char *) buffer);
   367    ei_class = e_ident[EI_CLASS];
   368    ei_data = e_ident[EI_DATA];
   369    switch (ei_class)
   370      {
   371      case ELFCLASS32:
   372        xlatefrom.d_size = sizeof (Elf32_Ehdr);
   373        if (elf32_xlatetom (&xlateto, &xlatefrom, ei_data) == NULL)
   374          goto out;
   375        e_type = ehdr.e32.e_type;
   376        phoff = ehdr.e32.e_phoff;
   377        phnum = ehdr.e32.e_phnum;
   378        phentsize = ehdr.e32.e_phentsize;
   379        if (phentsize != sizeof (Elf32_Phdr))
   380          goto out;
   381        /* NOTE if the number of sections is > 0xff00 then e_shnum
   382           is zero and the actual number would come from the section
   383           zero sh_size field. We ignore this here because getting shdrs
   384           is just a nice bonus (see below in the type == PT_LOAD case
   385           where we trim the last segment).  */
   386        shdrs_end = ehdr.e32.e_shoff + ehdr.e32.e_shnum * sizeof (Elf32_Shdr);
   387        break;
   388
   389      case ELFCLASS64:
   390        xlatefrom.d_size = sizeof (Elf64_Ehdr);
   391        if (elf64_xlatetom (&xlateto, &xlatefrom, ei_data) == NULL)
   392          goto out;
   393        e_type = ehdr.e64.e_type;
   394        phoff = ehdr.e64.e_phoff;
   395        phnum = ehdr.e64.e_phnum;
   396        phentsize = ehdr.e64.e_phentsize;
   397        if (phentsize != sizeof (Elf64_Phdr))
   398          goto out;
   399        /* See the NOTE above for shdrs_end and ehdr.e32.e_shnum.  */
   400        shdrs_end = ehdr.e64.e_shoff + ehdr.e64.e_shnum * sizeof (Elf64_Shdr);
   401        break;
   402
   403      default:
   404        goto out;
   405      }
   406
   407    /* The file header tells where to find the program headers.
   408       These are what we need to find the boundaries of the module.
   409       Without them, we don't have a module to report.  */
   410
   411    if (phnum == 0)
   412      goto out;
   413
   414    xlatefrom.d_type = xlateto.d_type = ELF_T_PHDR;
   415    xlatefrom.d_size = phnum * phentsize;
   416
   417    void *ph_buffer = NULL;
   418    size_t ph_buffer_size = 0;
   419    if (read_portion (&read_state, &ph_buffer, &ph_buffer_size,
   420                      start, segment,
   421                      start + phoff, xlatefrom.d_size))
   422      goto out;
   423
   424    /* ph_buffer_size will be zero if we got everything from the initial
   425       buffer, otherwise it will be the size of the new buffer that
   426       could be read.  */
   427    if (ph_buffer_size != 0)
   428      xlatefrom.d_size = ph_buffer_size;
   429
   430    xlatefrom.d_buf = ph_buffer;
   431
   432    bool class32 = ei_class == ELFCLASS32;
   433    size_t phdr_size = class32 ? sizeof (Elf32_Phdr) : sizeof (Elf64_Phdr);
   434    if (unlikely (phnum > SIZE_MAX / phdr_size))
   435      goto out;
   436    const size_t phdrsp_bytes = phnum * phdr_size;
   437    phdrsp = malloc (phdrsp_bytes);
   438    if (unlikely (phdrsp == NULL))
   439      goto out;
   440
   441    xlateto.d_buf = phdrsp;
   442    xlateto.d_size = phdrsp_bytes;
   443
   444    /* Track the bounds of the file visible in memory.  */
   445    GElf_Off file_trimmed_end = 0; /* Proper p_vaddr + p_filesz end.  */
   446    GElf_Off file_end = 0;         /* Rounded up to effective page size.  */
   447    GElf_Off contiguous = 0;       /* Visible as contiguous file from START.  */
   448    GElf_Off total_filesz = 0;     /* Total size of data to read.  */
   449
   450    /* Collect the bias between START and the containing PT_LOAD's p_vaddr.  */
   451    GElf_Addr bias = 0;
   452    bool found_bias = false;
   453
   454    /* Collect the unbiased bounds of the module here.  */
   455    GElf_Addr module_start = -1l;
   456    GElf_Addr module_end = 0;
   457    GElf_Addr module_address_sync = 0;
   458
   459    /* If we see PT_DYNAMIC, record it here.  */
   460    GElf_Addr dyn_vaddr = 0;
   461    GElf_Xword dyn_filesz = 0;
   462
   463    /* Collect the build ID bits here.  */
   464    struct elf_build_id build_id;
   465    build_id.memory = NULL;
   466    build_id.len = 0;
   467    build_id.vaddr =0;
   468
   469    Elf32_Phdr *p32 = phdrsp;
   470    Elf64_Phdr *p64 = phdrsp;
   471    if ((ei_class == ELFCLASS32
   472         && elf32_xlatetom (&xlateto, &xlatefrom, ei_data) == NULL)
   473        || (ei_class == ELFCLASS64
   474            && elf64_xlatetom (&xlateto, &xlatefrom, ei_data) == NULL))
   475      {
   476        found_bias = false; /* Trigger error check */
   477      }
   478    else
   479      {
   480        /* Consider each of the program headers we've read from the image.  */
   481        for (uint_fast16_t i = 0; i < phnum; ++i)
   482          {
   483            bool is32 = (ei_class == ELFCLASS32);
   484            GElf_Word type = is32 ? p32[i].p_type : p64[i].p_type;
   485            GElf_Addr vaddr = is32 ? p32[i].p_vaddr : p64[i].p_vaddr;
   486            GElf_Xword memsz = is32 ? p32[i].p_memsz : p64[i].p_memsz;
   487            GElf_Off offset = is32 ? p32[i].p_offset : p64[i].p_offset;
   488            GElf_Xword filesz = is32 ? p32[i].p_filesz : p64[i].p_filesz;
   489            GElf_Xword align = is32 ? p32[i].p_align : p64[i].p_align;
   490
   491            if (type == PT_DYNAMIC)
   492              {
   493                dyn_vaddr = vaddr;
   494                dyn_filesz = filesz;
   495              }
   496            else if (type == PT_NOTE)
   497              {
   498                /* If we have already seen a build ID, we don't care any more.  */
   499                if (build_id.memory != NULL || filesz == 0)
   500                  continue; /* Next header */
   501
   502                /* We calculate from the p_offset of the note segment,
   503                 because we don't yet know the bias for its p_vaddr.  */
   504                const GElf_Addr note_vaddr = start + offset;
   505                void *data;
   506                size_t data_size;
   507                if (read_portion (&read_state, &data, &data_size,
   508                                  start, segment, note_vaddr, filesz))
   509                  continue; /* Next header */
   510
   511                /* data_size will be zero if we got everything from the initial
   512                   buffer, otherwise it will be the size of the new buffer that
   513                   could be read.  */
   514                if (data_size != 0)
   515                  filesz = data_size;
   516
   517                assert (sizeof (Elf32_Nhdr) == sizeof (Elf64_Nhdr));
   518
   519                void *notes;
   520                if (ei_data == MY_ELFDATA)
   521                  notes = data;
   522                else
   523                  {
   524                    const unsigned int xencoding = ehdr.e32.e_ident[EI_DATA];
   525
   526                    notes = malloc (filesz);
   527                    if (unlikely (notes == NULL))
   528                      continue; /* Next header */
   529                    xlatefrom.d_type = xlateto.d_type = (align == 8
   530                                                         ? ELF_T_NHDR8
   531                                                         : ELF_T_NHDR);
   532                    xlatefrom.d_buf = (void *) data;
   533                    xlatefrom.d_size = filesz;
   534                    xlateto.d_buf = notes;
   535                    xlateto.d_size = filesz;
   536                    if (elf32_xlatetom (&xlateto, &xlatefrom, xencoding) == NULL)
   537                      {
   538                        free (notes);
   539                        finish_portion (&read_state, &data, &data_size);
   540                        continue;
   541                      }
   542                  }
   543
   544                const GElf_Nhdr *nh = notes;
   545                size_t len = 0;
   546                while (filesz > len + sizeof (*nh))
   547                  {
   548                    const void *note_name;
   549                    const void *note_desc;
   550
   551                    len += sizeof (*nh);
   552                    note_name = notes + len;
   553
   554                    len += nh->n_namesz;
   555                    len = align == 8 ? NOTE_ALIGN8 (len) : NOTE_ALIGN4 (len);
   556                    note_desc = notes + len;
   557
   558                    if (unlikely (filesz < len + nh->n_descsz))
   559                      break;
   560
   561                    if (nh->n_type == NT_GNU_BUILD_ID
   562                        && nh->n_descsz > 0
   563                        && nh->n_namesz == sizeof "GNU"
   564                        && !memcmp (note_name, "GNU", sizeof "GNU"))
   565                      {
   566                        build_id.vaddr = (note_desc
   567                                          - (const void *) notes
   568                                          + note_vaddr);
   569                        build_id.len = nh->n_descsz;
   570                        build_id.memory = malloc (build_id.len);
   570                        build_id.memory = malloc (build_id.len);
   571                        if (likely (build_id.memory != NULL))
   572                          memcpy (build_id.memory, note_desc, build_id.len);
   573                        break;
   574                      }
   575
   576                    len += nh->n_descsz;
   577                    len = align == 8 ? NOTE_ALIGN8 (len) : NOTE_ALIGN4 (len);
   578                    nh = (void *) notes + len;
   579                  }
   580
   581                if (notes != data)
   582                  free (notes);
   583                finish_portion (&read_state, &data, &data_size);
   584              }
   585            else if (type == PT_LOAD)
   586              {
   587                align = (dwfl->segment_align > 1
   588                         ? dwfl->segment_align : (align ?: 1));
   589
   590                GElf_Addr vaddr_end = (vaddr + memsz + align - 1) & -align;
   591                GElf_Addr filesz_vaddr = (filesz < memsz
   592                                          ? vaddr + filesz : vaddr_end);
   593                GElf_Off filesz_offset = filesz_vaddr - vaddr + offset;
   594
   595                if (file_trimmed_end < offset + filesz)
   596                  {
   597                    file_trimmed_end = offset + filesz;
   598
   599                    /* Trim the last segment so we don't bother with zeros
   600                       in the last page that are off the end of the file.
   601                       However, if the extra bit in that page includes the
   602                       section headers, keep them.  */
   603                    if (shdrs_end <= filesz_offset
   604                        && shdrs_end > file_trimmed_end)
   605                      {
   606                        filesz += shdrs_end - file_trimmed_end;
   607                        file_trimmed_end = shdrs_end;
   608                      }
   609                  }
   610
   611                total_filesz += filesz;
   612
   613                if (file_end < filesz_offset)
   614                  {
   615                    file_end = filesz_offset;
   616                    if (filesz_vaddr - start == filesz_offset)
   617                      contiguous = file_end;
   618                  }
   619
   620                if (!found_bias && (offset & -align) == 0
   621                    && likely (filesz_offset >= phoff + phnum * phentsize))
   622                  {
   623                    bias = start - vaddr;
   624                    found_bias = true;
   625                  }
   626
   627                if ((vaddr & -align) < module_start)
   628                  {
   629                    module_start = vaddr & -align;
   630                    module_address_sync = vaddr + memsz;
   631                  }
   632
   633                if (module_end < vaddr_end)
   634                  module_end = vaddr_end;
   635              }
